draw:
var FONT = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = FONT;
ctx.lineWidth = 1.4;

var ho = 9;                       // object height in cm
var f = p.focal;
var dob = p.objdist;
if (Math.abs(dob - f) < 1.5) dob = f + 1.5;
var di = 1 / (1 / f - 1 / dob);
var m = -di / dob;
var hi = m * ho;

var cx = W * 0.40, cy = H * 0.56;
var s = Math.min((cx - 18) / (dob + 8), (H * 0.34) / 12);
var X = function (d) { return cx + d * s; };
var Y = function (h) { return cy - h * s; };

// optic axis
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(6, cy); ctx.lineTo(W - 6, cy); ctx.stroke();

// the lens itself
var lh = H * 0.40;
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(cx, cy - lh);
ctx.quadraticCurveTo(cx + 9, cy, cx, cy + lh);
ctx.quadraticCurveTo(cx - 9, cy, cx, cy - lh);
ctx.stroke();

// focal points
var fp = [-f, f];
ctx.fillStyle = C.ink;
for (var k = 0; k < 2; k++) {
  var fx = X(fp[k]);
  ctx.beginPath(); ctx.arc(fx, cy, 2.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillText("F", fx - 3, cy + 15);
}

// object arrow
function arrow(x, ytail, ytip, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x, ytail); ctx.lineTo(x, ytip); ctx.stroke();
  var dir = ytip < ytail ? -1 : 1;
  ctx.beginPath();
  ctx.moveTo(x, ytip);
  ctx.lineTo(x - 4, ytip - dir * 7);
  ctx.lineTo(x + 4, ytip - dir * 7);
  ctx.closePath(); ctx.fill();
}
arrow(X(-dob), cy, Y(ho), C.ink);
ctx.fillStyle = C.ink;
ctx.fillText("object", X(-dob) - 18, Y(ho) - 8);

// image arrow
var ix = X(di);
if (ix > 4 && ix < W - 4) {
  arrow(ix, cy, Y(hi), C.accent);
  ctx.fillStyle = C.accent;
  ctx.fillText(di > 0 ? "real image" : "virtual image", ix - 22, Y(hi) + (hi > 0 ? -9 : 15));
}

// one refracted ray, given the height in cm where it crosses the lens
function refracted(ylcm) {
  var px0 = cx, py0 = Y(ylcm);
  var dx = X(di) - px0, dy = Y(hi) - py0;
  if (di < 0) { dx = -dx; dy = -dy; }
  var L = Math.sqrt(dx * dx + dy * dy) || 1;
  var far = W * 1.4;
  ctx.strokeStyle = C.rule;
  ctx.beginPath();
  ctx.moveTo(px0, py0);
  ctx.lineTo(px0 + dx / L * far, py0 + dy / L * far);
  ctx.stroke();
  if (di < 0) {
    ctx.setLineDash([3, 4]);
    ctx.beginPath(); ctx.moveTo(px0, py0); ctx.lineTo(X(di), Y(hi)); ctx.stroke();
    ctx.setLineDash([]);
  }
}

// ray 1: in parallel, out through the far focus
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(X(-dob), Y(ho)); ctx.lineTo(cx, Y(ho)); ctx.stroke();
refracted(ho);

// ray 2: straight through the middle
ctx.beginPath(); ctx.moveTo(X(-dob), Y(ho)); ctx.lineTo(cx, cy); ctx.stroke();
refracted(0);

// ray 3: in through the near focus, out parallel
var y3 = ho * (-f / (dob - f));
ctx.beginPath(); ctx.moveTo(X(-dob), Y(ho)); ctx.lineTo(cx, Y(y3)); ctx.stroke();
refracted(y3);

// a pulse of light running down the middle ray, so the direction is obvious
var seg = Math.abs(X(-dob) - cx);
var travel = (t * W * 0.30) % (seg + W * 0.55);
var mx, my;
if (travel < seg) {
  var u = travel / seg;
  mx = X(-dob) + (cx - X(-dob)) * u;
  my = Y(ho) + (cy - Y(ho)) * u;
} else {
  var dx2 = X(di) - cx, dy2 = Y(hi) - cy;
  if (di < 0) { dx2 = -dx2; dy2 = -dy2; }
  var L2 = Math.sqrt(dx2 * dx2 + dy2 * dy2) || 1;
  var r = travel - seg;
  mx = cx + dx2 / L2 * r;
  my = cy + dy2 / L2 * r;
}
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(mx, my, 3.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("lens, f = " + f.toFixed(0) + " cm", cx - 30, 14);

out.note = "object " + dob.toFixed(0) + " cm  |  image " + di.toFixed(1) + " cm " +
  (di > 0 ? "behind (real, inverted)" : "in front (virtual, upright)") +
  "  |  m = " + m.toFixed(2);

var FONT = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = FONT;
ctx.lineWidth = 1.4;

var R = p.radius;
if (Math.abs(R) < 10) R = R < 0 ? -10 : 10;
var f = R / 2;
var ho = 8;
var dob = p.objdist;
if (Math.abs(dob - f) < 1.5) dob = f + 1.5;
var di = 1 / (1 / f - 1 / dob);
var m = -di / dob;
var hi = m * ho;

var xp = W - 26, cy = H * 0.56;              // pole of the mirror
var s = Math.min((xp - 22) / (dob + 10), (H * 0.32) / 11);
var X = function (d) { return xp - d * s; }; // distances are positive in front
var Y = function (h) { return cy - h * s; };

ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(6, cy); ctx.lineTo(W - 6, cy); ctx.stroke();

// mirror surface: sagitta x = y^2 / 2R
var half = H * 0.38;
ctx.strokeStyle = C.figure;
ctx.beginPath();
for (var yy = -half; yy <= half; yy += 2) {
  var ycm = yy / s;
  var xx = xp - (ycm * ycm / (2 * R)) * s;
  yy === -half ? ctx.moveTo(xx, cy + yy) : ctx.lineTo(xx, cy + yy);
}
ctx.stroke();

// focus and centre of curvature
ctx.fillStyle = C.ink;
var pts = [[f, "F"], [R, "C"]];
for (var k = 0; k < 2; k++) {
  var px1 = X(pts[k][0]);
  if (px1 > 6 && px1 < W - 6) {
    ctx.beginPath(); ctx.arc(px1, cy, 2.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillText(pts[k][1], px1 - 3, cy + 15);
  }
}

function arrow(x, ytail, ytip, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x, ytail); ctx.lineTo(x, ytip); ctx.stroke();
  var dir = ytip < ytail ? -1 : 1;
  ctx.beginPath();
  ctx.moveTo(x, ytip); ctx.lineTo(x - 4, ytip - dir * 7); ctx.lineTo(x + 4, ytip - dir * 7);
  ctx.closePath(); ctx.fill();
}
arrow(X(dob), cy, Y(ho), C.ink);
ctx.fillStyle = C.ink;
ctx.fillText("object", X(dob) - 16, Y(ho) - 8);

var ix = X(di);
if (ix > 4 && ix < W - 4) {
  arrow(ix, cy, Y(hi), C.accent);
  ctx.fillStyle = C.accent;
  ctx.fillText(di > 0 ? "real" : "virtual", ix - 12, Y(hi) + (hi > 0 ? -9 : 15));
}

// reflected rays: they all pass through the image tip (or seem to)
function reflected(ylcm) {
  var px0 = xp - (ylcm * ylcm / (2 * R)) * s, py0 = Y(ylcm);
  var dx = X(di) - px0, dy = Y(hi) - py0;
  if (di < 0) { dx = -dx; dy = -dy; }
  var L = Math.sqrt(dx * dx + dy * dy) || 1;
  ctx.strokeStyle = C.rule;
  ctx.beginPath();
  ctx.moveTo(px0, py0);
  ctx.lineTo(px0 + dx / L * W * 1.3, py0 + dy / L * W * 1.3);
  ctx.stroke();
  if (di < 0) {
    ctx.setLineDash([3, 4]);
    ctx.beginPath(); ctx.moveTo(px0, py0); ctx.lineTo(X(di), Y(hi)); ctx.stroke();
    ctx.setLineDash([]);
  }
}

// incoming ray parallel to the axis, and one aimed at the pole
ctx.strokeStyle = C.rule;
var hitx = xp - (ho * ho / (2 * R)) * s;
ctx.beginPath(); ctx.moveTo(X(dob), Y(ho)); ctx.lineTo(hitx, Y(ho)); ctx.stroke();
reflected(ho);
ctx.beginPath(); ctx.moveTo(X(dob), Y(ho)); ctx.lineTo(xp, cy); ctx.stroke();
reflected(0);

// travelling pulse on the parallel ray
var seg = Math.abs(X(dob) - hitx);
var travel = (t * W * 0.28) % (seg + W * 0.5);
var mx, my;
if (travel < seg) {
  var u = travel / seg;
  mx = X(dob) + (hitx - X(dob)) * u;
  my = Y(ho);
} else {
  var dx2 = X(di) - hitx, dy2 = Y(hi) - Y(ho);
  if (di < 0) { dx2 = -dx2; dy2 = -dy2; }
  var L2 = Math.sqrt(dx2 * dx2 + dy2 * dy2) || 1;
  var r = travel - seg;
  mx = hitx + dx2 / L2 * r;
  my = Y(ho) + dy2 / L2 * r;
}
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(mx, my, 3.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText((R > 0 ? "concave" : "convex") + " mirror, f = " + f.toFixed(1) + " cm", 10, 14);

out.note = "R = " + R.toFixed(0) + " cm, f = R/2 = " + f.toFixed(1) + " cm  |  object " +
  dob.toFixed(0) + " cm  |  image " + di.toFixed(1) + " cm " +
  (di > 0 ? "in front (real)" : "behind (virtual)") + "  |  m = " + m.toFixed(2);

var FONT = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = FONT;
ctx.lineWidth = 1.4;

var n1 = 1.00, n2 = p.n2, R = p.radius, dob = p.objdist;
if (Math.abs(R) < 6) R = R < 0 ? -6 : 6;
var di = n2 / ((n2 - n1) / R - n1 / dob);

var cx = W * 0.46, cy = H * 0.55;
var s = Math.min((cx - 20) / (dob + 8), (H * 0.30) / 10);
var X = function (d) { return cx + d * s; };

// shade the second medium
ctx.fillStyle = C.paper;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(6, cy); ctx.lineTo(W - 6, cy); ctx.stroke();

// the curved surface
var half = H * 0.40;
ctx.strokeStyle = C.figure;
ctx.beginPath();
for (var yy = -half; yy <= half; yy += 2) {
  var ycm = yy / s;
  var xx = cx + (ycm * ycm / (2 * R)) * s;
  yy === -half ? ctx.moveTo(xx, cy + yy) : ctx.lineTo(xx, cy + yy);
}
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("n1 = 1.00 (air)", 10, 16);
ctx.fillText("n2 = " + n2.toFixed(2), W - 66, 16);
ctx.fillText("R = " + R.toFixed(0) + " cm", cx - 24, H - 8);

// object point
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(-dob), cy, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("O", X(-dob) - 3, cy - 10);

// two rays: along the axis, and one at a small height, bent to the image
var hs = [4, -4];
for (var k = 0; k < 2; k++) {
  var h = hs[k];
  var hy = cy - h * s;
  var hx = cx + (h * h / (2 * R)) * s;
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(X(-dob), cy); ctx.lineTo(hx, hy); ctx.stroke();
  var tx = X(di), ty = cy;
  var dx = tx - hx, dy = ty - hy;
  if (di < 0) { dx = -dx; dy = -dy; }
  var L = Math.sqrt(dx * dx + dy * dy) || 1;
  ctx.beginPath();
  ctx.moveTo(hx, hy);
  ctx.lineTo(hx + dx / L * W, hy + dy / L * W);
  ctx.stroke();
  if (di < 0) {
    ctx.setLineDash([3, 4]);
    ctx.beginPath(); ctx.moveTo(hx, hy); ctx.lineTo(tx, ty); ctx.stroke();
    ctx.setLineDash([]);
  }
}
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(X(-dob), cy); ctx.lineTo(W - 6, cy); ctx.stroke();

var ix = X(di);
if (ix > 6 && ix < W - 6) {
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(ix, cy, 4, 0, Math.PI * 2); ctx.fill();
  ctx.fillText("I", ix - 3, cy - 10);
}

out.note = "n1/do + n2/di = (n2 - n1)/R   gives   di = " + di.toFixed(1) + " cm " +
  (di > 0 ? "inside the second medium (real)" : "back on the object side (virtual)");
